1	const PROCESSING_FEE = 5;
2	const PREMIUM_PER_ITEM = 110;
3	
4	type Item = {
5	  type: string;
6	  material: string;
7	  enchantmentLevel: number;
8	  cursed: boolean;
9	};
10	
11	type Step = {
12	  op: string;
13	  items: Item[];
14	};
15	
16	type Scenario = {
17	  customer: { yearsWithMHPCO: number };
18	  steps: Step[];
19	};
20	
21	type QuoteResult = {
22	  premium: number;
23	};
24	
25	type ScenarioOutput = {
26	  results: QuoteResult[];
27	};
28	
29	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
30	  results: scenario.steps.map((step) => ({
31	    premium: step.items.length * PREMIUM_PER_ITEM + PROCESSING_FEE,
32	  })),
33	});
